import pathlib,json,hashlib,xml.etree.ElementTree as ET
r=pathlib.Path('.')
results=[]
for name,config,platform,defines,forced,suffix in [('config-debug-x64.json','Debug','x64','DEBUG=1;BASE=1','base.h','/debug'),('config-release-win32.json','Release','Win32','BASE=1','win32.h;base.h','/release')]:
 p=r/'tools/obj/rea'/name;a=json.loads(p.read_text(encoding='utf-8-sig'));items=a['Items'];first=items['ClCompile'][0]
 assert first['Identity']=='Actor.cpp' and first['PreprocessorDefinitions']==defines and first['ForcedIncludeFiles']==forced
 assert first['AdditionalIncludeDirectories'].endswith(suffix)
 assert len(items['ClCompile'])==2 and items['ClCompile'][1]['Identity']=='ACTOR.cpp' and items['ClCompile'][1]['PreprocessorDefinitions']=='DUPLICATE=1'
 assert items['ClInclude'][0]['Identity']=='Shared.h' and items['ClInclude'][0]['PreprocessorDefinitions']=='HEADER=1'
 results.append({'configuration':config,'platform':platform,'firstFile':first['Identity'],'definitions':defines,'forcedIncludes':forced,'includeSuffix':suffix,'compileItemCount':2,'headerItemCount':1,'evaluationOutputSHA256':hashlib.sha256(p.read_bytes()).hexdigest(),'assertionsPassed':True})
model=r/'CodeAssist.Indexing/ProjectCompilationModel.cs';fixture=r/'tests/ConfigurationParityFixture/ConfigurationParity.vcxproj'
xml=ET.parse(fixture);tags=[x.tag.split('}')[-1] for x in xml.iter()]
a={'scope':'Independent MSBuild fixture evaluation, not VA DLL execution or product-parity pass','fixture':str(fixture).replace('\\','/'),'fixtureSHA256':hashlib.sha256(fixture.read_bytes()).hexdigest(),'propsSHA256':hashlib.sha256((fixture.parent/'imported.props').read_bytes()).hexdigest(),'evaluations':results,'currentSourceReview':{'path':str(model).replace('\\','/'),'sha256':hashlib.sha256(model.read_bytes()).hexdigest(),'finding':'Current reader selects PropertyGroup/ItemDefinitionGroup descendants and substitutes ProjectDir/SolutionDir text; does not evaluate Import, metadata condition or ItemGroup file settings in this path.','fixturePropertyGroupCount':tags.count('PropertyGroup'),'fixtureItemDefinitionGroupCount':tags.count('ItemDefinitionGroup'),'fixtureImportCount':tags.count('Import'),'productRuntimeComparison':'not executed'},'designRequirements':['Evaluated project configuration and per-file metadata require a separate collector from raw generated-project candidate scanning.','Preserve Configuration/Platform and imported metadata inheritance; do not collapse all targets into one current context.','Apply per-file overrides to copied immutable option snapshot; cache admission must reject changed generation.','Keep raw candidate fallback visibly incomplete when compiler/evaluation backend unavailable.'],'remaining':['Run original VA inspection adapter on same fixture','Compare VS evaluated VCProjectEngine path with independent MSBuild fixture','Decide trusted project evaluation boundary and account for property functions/imports','Support general projects and Unreal without assuming all configurations are active'],'fullParityPassed':False}
(r/'docs/validation/configuration-fixture-evaluation.json').write_text(json.dumps(a,ensure_ascii=False,indent=2),encoding='utf-8')
p=r/'tools/BuildParitySpec.py';s=p.read_text(encoding='utf-8');needle="(r/'docs/integrated-spec.md').write_text"
insert="fixturePath=r/'docs/validation/configuration-fixture-evaluation.json'\nif fixturePath.exists():\n fixture=json.loads(fixturePath.read_text(encoding='utf-8'))\n data['configurationFixtureEvidence']='configuration-fixture-evaluation.json'\n (r/'docs/validation/integrated-spec.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')\n lines+=['','## 조건부 프로젝트·파일 구성 비교 입력','','[독립 MSBuild 평가 결과](validation/configuration-fixture-evaluation.json): import된 BASE 정의·파일별 Debug/Release include·Win32 강제 include·대소문자 중복 파일·header metadata를 포함한 작은 프로젝트를 Debug/x64와 Release/Win32로 평가했습니다. 예상 metadata 검증을 통과했습니다. VA DLL과 현재 CodeAssist product 경로를 실행 비교한 결과는 아닙니다.','', '현재 ProjectCompilationModel source 경로는 PropertyGroup/ItemDefinitionGroup에서 raw값을 읽고 ProjectDir/SolutionDir를 치환합니다. 이 경로의 Import·ItemGroup 파일 설정·조건 평가 누락을 source에서 확인했습니다. 전체 제품의 모든 구성 경로가 없다고 단정하지 않습니다.','']\n lines+=['- '+x for x in fixture['designRequirements']]\n lines+=['','원본 adapter·VCProjectEngine와 같은 입력의 실행 비교가 남아 있으므로 전체 동등성0/108 유지.']\n"
if insert not in s:s=s.replace(needle,insert+needle,1)
